/// <summary>
/// The batch side of a wall-to-wall count (HSMobileOpsCountWallToWall): building its journal,
/// posting it, or cancelling it. Retryable: each step is safe to run again after a crash.
/// </summary>
class HSMobileOpsCountWallToWallBatch extends RunBaseBatch implements BatchRetryable
{
    RefRecId freezeRecId;
    str      operation;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        freezeRecId,
        operation
    #endmacro
}

Method.Source:
[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}

public RefRecId parmFreezeRecId(RefRecId _value = freezeRecId)
{
    freezeRecId = _value;
    return freezeRecId;
}

public str parmOperation(str _value = operation)
{
    operation = _value;
    return operation;
}

/// <summary>One batch run of the step; answers its job, for the freeze to keep.</summary>
public static RefRecId schedule(RefRecId _freezeRecId, str _operation, str _caption)
{
    HSMobileOpsCountWallToWallBatch task = new HSMobileOpsCountWallToWallBatch();
    BatchHeader                     batchHeader;

    task.parmFreezeRecId(_freezeRecId);
    task.parmOperation(_operation);
    batchHeader = BatchHeader::construct();
    batchHeader.parmCaption(_caption);
    batchHeader.addTask(task);
    batchHeader.save();
    return batchHeader.parmBatchHeaderId();
}

public void run()
{
    if (operation == HSMobileOpsCountWallToWallBatch::opBuild())
    {
        HSMobileOpsCountWallToWall::runBuild(freezeRecId);
    }
    else if (operation == HSMobileOpsCountWallToWallBatch::opPost())
    {
        HSMobileOpsCountWallToWall::runPost(freezeRecId);
    }
    else if (operation == HSMobileOpsCountWallToWallBatch::opCancel())
    {
        HSMobileOpsCountWallToWall::runCancel(freezeRecId);
    }
}

public static ClassDescription description()
{
    return 'Mobile ops: wall-to-wall count';
}

public boolean unpack(container _packedClass)
{
    int version = RunBase::getVersion(_packedClass);

    if (version == #CurrentVersion)
    {
        [version, #CurrentList] = _packedClass;
        return true;
    }
    return false;
}
